import asyncio

from async_timeout import timeout


async def main():
    loop = asyncio.get_running_loop()
    for expired in (False, True):
        try:
            async with timeout(0 if expired else 60) as t:
                await asyncio.sleep(0.01 if expired else 0)
        except asyncio.TimeoutError:
            print("Timeout occurred")
        original_deadline = t.deadline
        for method, value in (("shift", 1.0), ("update", loop.time() + 1.0)):
            try:
                getattr(t, method)(value)
            except RuntimeError as exc:
                print(f"{method} after {'expiration' if expired else 'exit'}: {exc}")
            else:
                raise AssertionError(f"{method} unexpectedly succeeded")
            assert t.deadline == original_deadline


asyncio.run(main())
